#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header line removed"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other booking removed"; fail=1; }

# not found: exit 1, message on stderr only
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); rc=$?
[ "$rc" = 1 ] || { echo "not found should exit 1, got $rc"; fail=1; }
[ -z "$out" ] || { echo "not found should print nothing on stdout: $out"; fail=1; }
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null)
[ "$err" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found message: $err"; fail=1; }

# usage: exit 2, usage on stderr only
out=$(bash src/cancel.sh aoi 2>/dev/null); rc=$?
[ "$rc" = 2 ] || { echo "usage should exit 2, got $rc"; fail=1; }
[ -z "$out" ] || { echo "usage should print nothing on stdout: $out"; fail=1; }
err=$(bash src/cancel.sh aoi 2>&1 >/dev/null)
[ "$err" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage message: $err"; fail=1; }

# same date and start in another room: only the named room's booking is removed
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$t2"
BOOKINGS=$t2 bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel aoi failed"; fail=1; }
! grep -q '^aoi' "$t2" || { echo "aoi booking still there"; fail=1; }
grep -q '^kaede.2026-01-05.09:00' "$t2" || { echo "kaede booking removed by cancel of aoi"; fail=1; }
rm -f "$t2"

rm -f "$t"; exit $fail

